<template>
  <section class="flex flex-col w-full gap-6">
    <PageTitle :title="`${userDetails.first_name} ${userDetails.last_name}`" />
    <section class="flex flex-col gap-4">
      <GoBackButton subject="user" :fallback-to="{ name: 'users-id', params: { id: userId } }" />
      <CanvasserFormWrapper title="Edit Profile">
        <AppEmpty
          v-if="!isProfileEditable"
          title="Profile not editable"
          description="An admin's profile cannot be edited."
        />
        <AppLoader v-else-if="isLoading && !profileDetails" subject="profile" />
        <AppError v-else-if="error" :error="error" title="Failed to load profile" />
        <ProfileEditForm
          v-else
          :initial-data="initialData"
          :can-edit-bio-text="true"
          guard-unsaved-changes
          :is-saving="isSaving"
          :on-submit="onSubmit"
        />
      </CanvasserFormWrapper>
    </section>
  </section>
</template>

<script setup lang="ts">
import type { GetUserDetailsResponse } from '~/client';
import { profileAnswersFromDetails } from '~/utils/profileAnswersFromDetails';
import { useProfileDetails } from '~/queries/users/profile';
import { canAdminManageProfile } from '~/utils/profileEditPermissions';

definePageMeta({
  roles: ['admin'],
});

const { userDetails } = defineProps<{ userDetails: NonNullable<GetUserDetailsResponse> }>();

const userId = computed(() => userDetails.id);
const { userId: myUserId } = useUserRole();
// Mirror the button-gating in UserDetailsProfile: a direct navigation to this URL must
// not reach the form for a profile this admin may not manage (another admin's).
const isProfileEditable = computed(() => canAdminManageProfile(userDetails.role, userId.value === myUserId.value));

useHead({ title: 'Edit Profile' });

const { profileDetails, isLoading, error } = useProfileDetails(userId);

const initialData = computed(() => ({
  profile_picture_url: profileDetails.value?.profile_picture_url ?? null,
  bio: profileDetails.value?.bio ?? null,
  answers: profileAnswersFromDetails(profileDetails.value),
}));

const { onSubmit, isSaving } = useProfileEditSubmit('admin', userId, initialData);
</script>
